/**
 * PointsTransaction, as stored.
 */
final class PointsTransaction
{
    private function __construct(
        private readonly EntityId $id,
        private readonly EdgeLoader $edges,
        private readonly int $value,
    ) {
    }

    public function getId(): EntityId
    {
        return $this->id;
    }

    public function getValue(): int
    {
        return $this->value;
    }

    /**
     * @return User|null
     */
    public function getUser(): ?User
    {
        $related = $this->edges->toOne('PointsTransaction', $this->id, 'user');
        assert(null === $related || $related instanceof User);

        return $related;
    }

    /**
     * @return User|null
     */
    public function getReference(): ?User
    {
        $related = $this->edges->toOne('PointsTransaction', $this->id, 'reference');
        assert(null === $related || $related instanceof User);

        return $related;
    }

    public static function of(EntityId $id, EdgeLoader $edges, int $value): self
    {
        return new self($id, $edges, $value);
    }
}

