namespace App\Elephentity;

use App\Elephentity\PointsTransaction\PointsTransactionHydrator;
use App\Elephentity\PointsTransaction\PointsTransactionInput;
use App\Elephentity\PointsTransaction\PointsTransactionReadPolicies;
use App\Elephentity\PointsTransaction\PointsTransactionTriggers;
use App\Elephentity\PointsTransaction\PointsTransactionVerifiers;
use App\Elephentity\PointsTransaction\PointsTransactionWritePolicies;
use App\Elephentity\User\UserHydrator;
use App\Elephentity\User\UserInput;
use App\Elephentity\User\UserReadPolicies;
use App\Elephentity\User\UserTriggers;
use App\Elephentity\User\UserVerifiers;
use App\Elephentity\User\UserWritePolicies;
use Closure;
use Eleph\Runtime\Query\ValueDecoder;
use Psr\Container\ContainerInterface;

/**
 * Every generated class this project's container must be able to build.
 */
final class Wiring
{
    /**
     * The hand-written Contract bindings are not here: BootCheck enforces those
     * separately, against contracts() on the catalogue.
     *
     * @return array<class-string, Closure(ContainerInterface): object>
     */
    public static function registrations(): array
    {
        return [
            PointsTransactionHydrator::class => static fn (ContainerInterface $c): object => new PointsTransactionHydrator(self::resolve($c, ValueDecoder::class)),
            PointsTransactionInput::class => static fn (ContainerInterface $c): object => new PointsTransactionInput(self::resolve($c, ValueDecoder::class)),
            PointsTransactionTriggers::class => static fn (ContainerInterface $c): object => new PointsTransactionTriggers(),
            PointsTransactionVerifiers::class => static fn (ContainerInterface $c): object => new PointsTransactionVerifiers(),
            PointsTransactionReadPolicies::class => static fn (ContainerInterface $c): object => new PointsTransactionReadPolicies(),
            PointsTransactionWritePolicies::class => static fn (ContainerInterface $c): object => new PointsTransactionWritePolicies(),
            UserHydrator::class => static fn (ContainerInterface $c): object => new UserHydrator(self::resolve($c, ValueDecoder::class)),
            UserInput::class => static fn (ContainerInterface $c): object => new UserInput(self::resolve($c, ValueDecoder::class)),
            UserTriggers::class => static fn (ContainerInterface $c): object => new UserTriggers(),
            UserVerifiers::class => static fn (ContainerInterface $c): object => new UserVerifiers(),
            UserReadPolicies::class => static fn (ContainerInterface $c): object => new UserReadPolicies(),
            UserWritePolicies::class => static fn (ContainerInterface $c): object => new UserWritePolicies(),
        ];
    }

    /**
     * @template T of object
     * @param class-string<T> $class
     * @return T
     */
    private static function resolve(ContainerInterface $c, string $class): object
    {
        $service = $c->get($class);

        assert($service instanceof $class);

        return $service;
    }
}
